<?php require __DIR__.'/config/database.php';require __DIR__.'/v1_nav.php';$rows=$pdo->query("SELECT t.*,us.nickname,us.custom_brand,us.custom_model FROM tags t LEFT JOIN user_shoes us ON us.id=t.user_shoe_id ORDER BY t.id DESC")->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tags — TapSole</title><link rel="stylesheet" href="assets/v1.css"></head><body><main class="app"><div class="top"><div class="brand">TAPSOLE<i></i></div><a class="avatar" href="settings.php">G</a></div><div class="kicker">YOUR HARDWARE</div><h1 class="pageTitle">TapSole tags.</h1><?php foreach($rows as $t):$nm=$t['nickname']?:trim(($t['custom_brand']??'').' '.($t['custom_model']??''));?><div class="tagcard"><div class="tagid"><?=htmlspecialchars($t['tag_code'])?></div><div class="tagshoe"><?=htmlspecialchars($nm?:'Ready to activate')?></div><div class="tagstatus"><span class="dot"></span><?=htmlspecialchars($t['activation_status'])?></div></div><?php endforeach;?><div class="card"><div class="kicker">PASSIVE NFC</div><p style="font-size:13px;line-height:1.55;color:#777;margin-bottom:0">A TapSole tag selects a shoe. No battery, GPS or location tracking.</p></div><a class="fab" href="tag_new.php">＋</a><?php v1nav('tags');?></main></body></html>